import assert from 'node:assert/strict';import{readFile,writeFile,mkdir}from'node:fs/promises';import{resolve}from'node:path';import{preview}from'vite';import{chromium}from'playwright';import{createClient}from'@supabase/supabase-js';import{sessaoQa}from'./sessoes-qa-concorrencia-20261116.mjs';
